@Command(name = "mycli", subcommands = {AddTaskCommand.class})
static class TaskCliCommand implements Runnable {
    final List<Task> tasks = new ArrayList<>();
    public void run() { }
}

@Command(name = "add")
static class AddTaskCommand implements Runnable {
    @ParentCommand TaskCliCommand parent;
    @Parameters(index = "0") String name;
    @Option(names = "--priority", defaultValue = "3") int priority;
    @Spec CommandLine.Model.CommandSpec spec;
    public void run() {
        if (priority < 1 || priority > 5)
            throw new ParameterException(spec.commandLine(), "Priorytet musi byc 1-5");
        parent.tasks.add(new Task(name, priority));
    }
}

static class Selector {
    @Option(names = "--id") Integer id;
    @Option(names = "--name") String name;
}
@ArgGroup(exclusive = true, multiplicity = "1")
Selector selector; // dokladnie jedno z dwoch
